-- =========================================================
-- support_tickets_db schema
-- =========================================================
DROP TABLE IF EXISTS tickets;

CREATE TABLE tickets (
    ticket_id           SERIAL PRIMARY KEY,
    domain              TEXT NOT NULL DEFAULT 'ecommerce',
    title               TEXT NOT NULL,
    description         TEXT NOT NULL,
    resolution_notes    TEXT,
    status              TEXT NOT NULL,        -- open / in_progress / resolved / closed
    priority            TEXT NOT NULL,        -- low / medium / high / critical
    category            TEXT NOT NULL,        -- refund / shipping / damaged_item / wrong_item / account / payment
    assignee            TEXT,
    reporter            TEXT,
    carrier             TEXT,                 -- FedEx / UPS / USPS / DHL
    tracking_number     TEXT,
    shipping_status     TEXT,                 -- in_transit / delayed / delivered / lost
    estimated_delivery  DATE,
    order_id            TEXT,
    created_at          TIMESTAMP NOT NULL,
    resolved_at         TIMESTAMP,
    metadata            JSONB
);

-- Helpful indexes for the SQL side of your RAG+SQL queries
CREATE INDEX idx_tickets_status ON tickets(status);
CREATE INDEX idx_tickets_category ON tickets(category);
CREATE INDEX idx_tickets_created_at ON tickets(created_at);

